-- 68 Moon Lander: the autopilot is fixed_update - called once before every
-- physics step with the step's dt, reading where the module is after the
-- last step - so it flies the same whatever the frame rate. update only
-- draws the flame and the log. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/68-moon-lander.scene"
local PAD_X, PAD_Y = 120.0, -201.0
local MASS, G = 10, 162            -- the Moon's 1.62 m/s, a hundred units a metre
local MAX_UP, MAX_SIDE = 520, 90
local STARTS = { { -420, 220 }, { 470, 240 }, { -180, 260 }, { 300, 180 }, { -520, 120 } }
local captions = true
local module, flame, dust, dust_left, status
local landing, start, phase, wait = 0, 1, "flying", 0
local thrust, log = 0, ""

local function clamp(v, lo, hi) return math.max(lo, math.min(hi, v)) end

local function begin(i)
    start = i
    phase, wait, landing = "flying", 0, landing + 1
    Transform.set_position(module, STARTS[i][1], STARTS[i][2])
    Physics.set_velocity(module, (i % 2 == 0) and -40 or 50, 0)
end

function init(entity)
    module = Entity.find_by_name("Module")
    flame = Entity.find_by_name("Flame")
    dust = Entity.find_by_name("Dust")
    dust_left = Entity.find_by_name("DustLeft")
    status = Entity.find_by_name("Status")
    Physics.set_gravity(0, -1.62)
    begin(1)
end

-- The autopilot, a step at a time: steer over the pad, and come down at a
-- speed that shrinks with the height left.
function fixed_update(entity, dt)
    if phase ~= "flying" then thrust = 0 return end
    local x, y = Transform.get_position(module)
    local vx, vy = Physics.get_velocity(module)
    local alt = y - 37 - (PAD_Y + 5)     -- the feet over the pad's top
    local ax = clamp((PAD_X - x) * 0.9 - vx * 1.8, -MAX_SIDE, MAX_SIDE)
    local want = -clamp(alt * 0.7, 12, 150)
    -- Not over the pad yet: hold a hundred and forty up, come down after.
    if math.abs(PAD_X - x) > 50 then want = math.max(want, clamp((140 - alt) * 1.2, -150, 80)) end
    local ay = clamp((want - vy) * 4 + G, 0, MAX_UP)
    thrust = ay / MAX_UP
    Physics.apply_force(module, ax * MASS, ay * MASS)
    if alt < 3 and math.abs(vy) < 25 then
        phase = "down"
        log = "landing " .. landing .. ":  " .. math.floor(math.abs(x - PAD_X) + 0.5) .. " from the pad's centre, touched at "
            .. string.format("%.1f", math.abs(vy)) .. " a second"
        if dust then Particles.emit_burst(dust, 60) end
        if dust_left then Particles.emit_burst(dust_left, 60) end
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then begin(start % #STARTS + 1) end
    if flame then Particles.set_rate(flame, 700 * thrust) end
    if phase == "down" then
        wait = wait + dt
        if wait > 3 then begin(start % #STARTS + 1) end
    end
    if status then UI.set_text(status, log) end
end
